#pragma config(Sensor, S1, microphone1, sensorSoundDB)#pragma config(Sensor, S2, microphone2, sensorSoundDB)#pragma config(Sensor, S3, microphone3, sensorSoundDB)#pragma config(Sensor, S4, microphone4, sensorSoundDB)//*!!Code automatically generated by 'ROBOTC' configuration wizard               !!*//int lighting_time = 70;int darkening_time = 35;int clap_threshold = 50;int clap_reset_threshold = 25;int sound_capture_time = 60;int microphoneValues[4];int packet_id = 1;int anyMicrophoneAbove(int threshold){    if (SensorValue[microphone1] > threshold)    {        return 1;    }    if (SensorValue[microphone2] > threshold)    {        return 1;    }    if (SensorValue[microphone3] > threshold)    {        return 1;    }    if (SensorValue[microphone4] > threshold)    {        return 1;    }    return 0;}void waitForClap(){    eraseDisplay();    displayTextLine(0, "SLAVE READY");    displayTextLine(2, "Waiting for clap");    while (true)    {        if (!bSoundActive && anyMicrophoneAbove(clap_threshold))        {            break;        }        sleep(1);    }}void captureMicrophoneMaximums(){    microphoneValues[0] = SensorValue[microphone1];    microphoneValues[1] = SensorValue[microphone2];    microphoneValues[2] = SensorValue[microphone3];    microphoneValues[3] = SensorValue[microphone4];    clearTimer(T1);    while (getTimer(T1, milliseconds) < sound_capture_time)    {        if (!bSoundActive)        {            if (SensorValue[microphone1] > microphoneValues[0])            {                microphoneValues[0] = SensorValue[microphone1];            }            if (SensorValue[microphone2] > microphoneValues[1])            {                microphoneValues[1] = SensorValue[microphone2];            }            if (SensorValue[microphone3] > microphoneValues[2])            {                microphoneValues[2] = SensorValue[microphone3];            }            if (SensorValue[microphone4] > microphoneValues[3])            {                microphoneValues[3] = SensorValue[microphone4];            }        }        sleep(1);    }}void sendLightBit(int bitValue){    if (bitValue == 1)    {        setMotorSpeed(motorA, -100);    }    else    {        setMotorSpeed(motorA, 0);    }    sleep(lighting_time);    setMotorSpeed(motorA, 0);    sleep(darkening_time);}void sendBinaryValue(int value, int bitCount){    int bitPosition;    int bitValue;    for (bitPosition = bitCount - 1; bitPosition >= 0; bitPosition--)    {        bitValue = (value >> bitPosition) & 1;        sendLightBit(bitValue);    }}void transmitPacket(){    eraseDisplay();    displayTextLine(0, "TRANSMITTING");    displayTextLine(2, "ID: %d", packet_id);    displayTextLine(3, "%d %d", microphoneValues[0], microphoneValues[1]);    displayTextLine(4, "%d %d", microphoneValues[2], microphoneValues[3]);    sendBinaryValue(20, 5);    sendBinaryValue(packet_id, 5);    sendBinaryValue(microphoneValues[0], 7);    sendBinaryValue(microphoneValues[1], 7);    sendBinaryValue(microphoneValues[2], 7);    sendBinaryValue(microphoneValues[3], 7);    sendBinaryValue(5, 5);    setMotorSpeed(motorA, 0);}task main(){    setMotorSpeed(motorA, 0);    waitForClap();    captureMicrophoneMaximums();    transmitPacket();    eraseDisplay();    displayTextLine(0, "FINISHED");    setMotorTarget(motorB, -200, 20);    setMotorTarget(motorC, -200, 20);    sleep(1500);    while (true)    {        setMotorTarget(motorB, -210, 40);        setMotorTarget(motorC, -150, 40);        sleep(500);        setMotorTarget(motorC, -210, 40);        setMotorTarget(motorB, -150, 40);        sleep(500);    }}